INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch09$PT143-S3-Q3$batch09$, 143, 3, 3, $batch09$Principle-Strengthen$batch09$, $batch09$Louise McBride, a homeowner, filed a complaint against a nearby nightclub through the Licensing Bureau, a government agency. Although regulations clearly state that Form 283 is to be used for formal complaints, Bureau staff gave McBride Form 5, which she used with the intention of filing a formal complaint. The nightclub argues that the complaint should be dismissed because the incorrect form was used. But that would be unfair.$batch09$, $batch09$Which one of the following principles, if valid, most helps to justify the judgment that dismissing the complaint would be unfair?$batch09$, $batch09$C$batch09$, true, $batch09$Batch 09; question text from local bank.$batch09$ FROM lr_sections s WHERE s.preptest=143 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch09$PT143-S3-Q3$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$A$batch09$, $batch09$People who wish to file complaints through the Licensing Bureau should be informed of all relevant regulations.$batch09$, $batch09$Wrong Outcome$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT143-S3-Q3$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$A$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$B$batch09$, $batch09$Government agencies should make their forms straightforward enough that completing them will not be unduly burdensome for the average person.$batch09$, $batch09$Wrong Problem$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT143-S3-Q3$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$B$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$C$batch09$, $batch09$It is unfair for someone’s complaint to be dismissed because of an incorrect action on the part of a government agency.$batch09$, $batch09$Correct$batch09$, true FROM lr_questions q WHERE q.qid=$batch09$PT143-S3-Q3$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$C$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$D$batch09$, $batch09$A government agency should not make its procedures so complex that even the agency’s employees cannot understand the procedures.$batch09$, $batch09$Not Shown$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT143-S3-Q3$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$D$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch09$E$batch09$, $batch09$It is unfair for a business to be subject to a formal complaint unless the complaint is made in a way that provides the business with an opportunity to defend itself.$batch09$, $batch09$Wrong Side$batch09$, false FROM lr_questions q WHERE q.qid=$batch09$PT143-S3-Q3$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch09$E$batch09$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch09$PT143-S3-Q3$batch09$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch09$Conclusion$batch09$, $batch09$Dismissing McBride's complaint would be unfair.$batch09$), (1, $batch09$Evidence$batch09$, $batch09$The rules call for Form 283, but Bureau staff gave McBride Form 5. McBride used it intending to file a formal complaint.$batch09$), (2, $batch09$Evaluate$batch09$, $batch09$The wrong form came from the government agency, not from McBride. McBride did what the staff said. The principle needs to connect "the mistake was the agency's" to "dismissing the complaint is unfair."$batch09$), (3, $batch09$Goal$batch09$, $batch09$It's unfair to dismiss someone's complaint because of a government agency's mistake.$batch09$)) v(position,label,body) WHERE q.qid=$batch09$PT143-S3-Q3$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch09$A$batch09$, $batch09$This says people should be told the regulations. Even if McBride should have been told, A doesn't say anything about whether dismissal would be unfair.$batch09$), ($batch09$B$batch09$, $batch09$The issue isn't that Form 5 was hard to fill out. It's that it was the wrong form. And B says nothing about dismissal.$batch09$), ($batch09$C$batch09$, $batch09$The incorrect action was the Bureau staff handing over Form 5, and the Bureau is a government agency. So dismissing the complaint for that reason is unfair. That's the conclusion.$batch09$), ($batch09$D$batch09$, $batch09$We know staff handed out the wrong form, not that the procedures are too complex for them. And D tells agencies how to design procedures. It doesn't say dismissing the complaint is unfair.$batch09$), ($batch09$E$batch09$, $batch09$This protects the nightclub. Nothing says the nightclub lacked a chance to defend itself, and the conclusion is about fairness to McBride.$batch09$)) v(letter,body) WHERE q.qid=$batch09$PT143-S3-Q3$batch09$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
